     1→/**
     2→ * Public API endpoint for the storefront zip code widget.
     3→ *
     4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
     5→ * to check whether a zip code is serviceable.
     6→ *
     7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
     8→ *
     9→ * Response:
    10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
    11→ *   200 { allowed: false, message: "..." }
    12→ *   400 { error: "Missing shop or zip parameter" }
    13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
    14→ */
    15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
    16→import db from "../db.server";
    17→
    18→const CORS_HEADERS = {
    19→  "Access-Control-Allow-Origin": "*",
    20→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    21→  "Access-Control-Allow-Headers": "Content-Type",
    22→  "Content-Type": "application/json",
    23→};
    24→
    25→// Applied only to successful ZIP check responses (200) to reduce DB load
    26→// for repeated lookups of the same ZIP code from the same storefront visitor.
    27→const SUCCESS_HEADERS = {
    28→  ...CORS_HEADERS,
    29→  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
    30→};
    31→
    32→const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
    33→
    34→async function handleZipCheck(shop: string | null, zip: string | null) {
    35→  if (!shop || !zip) {
    36→    return new Response(
    37→      JSON.stringify({ error: "Missing shop or zip parameter" }),
    38→      { status: 400, headers: CORS_HEADERS },
    39→    );
    40→  }
    41→
    42→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
    43→  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
    44→    return new Response(
    45→      JSON.stringify({ error: "Invalid shop parameter" }),
    46→      { status: 400, headers: CORS_HEADERS },
    47→    );
    48→  }
    49→
    50→  // Enforce input length limits to prevent abuse
    51→  if (zip.length > 20) {
    52→    return new Response(
    53→      JSON.stringify({ error: "Invalid zip code" }),
    54→      { status: 400, headers: CORS_HEADERS },
    55→    );
    56→  }
    57→
    58→  const normalizedZip = zip.trim().toUpperCase();
    59→
    60→  const zipRecord = await db.zipCode.findUnique({
    61→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
    62→  });
    63→
    64→  // Fetch widget config for custom messages (falls back to defaults)
    65→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
    66→
    67→  // Fetch shop settings to determine default behavior for unlisted zip codes
    68→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
    69→  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
    70→
    71→  if (!zipRecord || !zipRecord.isActive) {
    72→    const notFoundMsg =
    73→      widgetConfig?.notFoundMessage ??
    74→      "This zip code was not found in our system.";
    75→
    76→    // If the zip is simply not in the list (not inactive) and the merchant
    77→    // has set defaultBehavior to "allow", treat it as an allowed zip
    78→    if (!zipRecord && defaultBehavior === "allow") {
    79→      const successMsg =
    80→        widgetConfig?.successMessage ?? "We deliver to your area!";
    81→      return new Response(
    82→        JSON.stringify({
    83→          allowed: true,
    84→          message: successMsg,
    85→          eta: null,
    86→          zone: null,
    87→          showWaitlist: false,
    88→          cutoffTime: null,
    89→          daysOfWeek: null,
    90→        }),
    91→        { status: 200, headers: SUCCESS_HEADERS },
    92→      );
    93→    }
    94→
    95→    if (!zipRecord) {
    96→      return new Response(
    97→        JSON.stringify({
    98→          allowed: false,
    99→          message: notFoundMsg,
   100→          notFound: true,
   101→        }),
   102→        { status: 200, headers: SUCCESS_HEADERS },
   103→      );
   104→    }
   105→
   106→    // Inactive zip — treat same as not found regardless of defaultBehavior
   107→    return new Response(
   108→      JSON.stringify({ allowed: false, message: notFoundMsg, notFound: true }),
   109→      { status: 200, headers: SUCCESS_HEADERS },
   110→    );
   111→  }
   112→
   113→  if (zipRecord.type === "blocked") {
   114→    const errorMsg =
   115→      zipRecord.message ??
   116→      widgetConfig?.errorMessage ??
   117→      "Sorry, we don't deliver to this area yet.";
   118→
   119→    return new Response(
   120→      JSON.stringify({ allowed: false, message: errorMsg }),
   121→      { status: 200, headers: SUCCESS_HEADERS },
   122→    );
   123→  }
   124→
   125→  // Fetch the most relevant active DeliveryRule for this zip.
   126→  // Priority 1: rules that explicitly list this zip in their zipCodes field.
   127→  // Priority 2: rules that match by zone (with no explicit zip list).
   128→  // Within each priority tier, order by `priority ASC` (lower = higher priority).
   129→  const zipCodeUpper = normalizedZip;
   130→  const zipZone = zipRecord.zone ?? null;
   131→
   132→  // Fetch all active rules for the shop ordered by priority so we can apply
   133→  // the matching logic in a single query result.
   134→  const activeRules = await db.deliveryRule.findMany({
   135→    where: { shop, isActive: true },
   136→    orderBy: { priority: "asc" },
   137→  });
   138→
   139→  let matchedRule: (typeof activeRules)[number] | null = null;
   140→
   141→  // Pass 1: explicit zip match — zipCodes field contains this zip code
   142→  for (const rule of activeRules) {
   143→    if (rule.zipCodes) {
   144→      const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
   145→      if (zips.includes(zipCodeUpper)) {
   146→        matchedRule = rule;
   147→        break;
   148→      }
   149→    }
   150→  }
   151→
   152→  // Pass 2: zone match — rule's zone matches the zip's zone and no explicit zip list
   153→  if (!matchedRule && zipZone) {
   154→    for (const rule of activeRules) {
   155→      if (
   156→        rule.zone === zipZone &&
   157→        (!rule.zipCodes || rule.zipCodes.trim() === "")
   158→      ) {
   159→        matchedRule = rule;
   160→        break;
   161→      }
   162→    }
   163→  }
   164→
   165→  // Allowed
   166→  const successMsg =
   167→    zipRecord.message ??
   168→    widgetConfig?.successMessage ??
   169→    "Great news! We deliver to your area.";
   170→
   171→  return new Response(
   172→    JSON.stringify({
   173→      allowed: true,
   174→      message: successMsg,
   175→      eta: widgetConfig?.showEta ? (zipRecord.eta ?? null) : null,
   176→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
   177→      showWaitlist: false,
   178→      cutoffTime: matchedRule?.cutoffTime ?? null,
   179→      daysOfWeek: matchedRule?.daysOfWeek ?? null,
   180→    }),
   181→    { status: 200, headers: SUCCESS_HEADERS },
   182→  );
   183→}
   184→
   185→// Handle GET requests: ?shop=...&zip=...
   186→export const loader = async ({ request }: LoaderFunctionArgs) => {
   187→  const url = new URL(request.url);
   188→
   189→  // Handle CORS preflight
   190→  if (request.method === "OPTIONS") {
   191→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   192→  }
   193→
   194→  const shop = url.searchParams.get("shop");
   195→  const zip = url.searchParams.get("zip");
   196→  return handleZipCheck(shop, zip);
   197→};
   198→
   199→// Handle POST requests with JSON body: { shop, zip }
   200→export const action = async ({ request }: ActionFunctionArgs) => {
   201→  let shop: string | null = null;
   202→  let zip: string | null = null;
   203→
   204→  try {
   205→    const body = await request.json();
   206→    shop = body?.shop ?? null;
   207→    zip = body?.zip ?? null;
   208→  } catch {
   209→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
   210→      status: 400,
   211→      headers: CORS_HEADERS,
   212→    });
   213→  }
   214→
   215→  return handleZipCheck(shop, zip);
   216→};
   217→

