     1→{% comment %}
     2→  Zip Code Checker — Theme App Extension Block
     3→  Add this block to any section in the Shopify Theme Editor.
     4→  The block automatically connects to your app — no manual configuration needed.
     5→{% endcomment %}
     6→
     7→{% if request.design_mode %}
     8→  {% comment %}
     9→    Theme Editor preview — render a static placeholder so no live API calls
    10→    are made during theme customization. The real widget loads on the storefront.
    11→  {% endcomment %}
    12→  <div style="
    13→    background:#ffffff;
    14→    border:1px solid #e1e3e5;
    15→    border-radius:8px;
    16→    padding:24px;
    17→    max-width:480px;
    18→    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
    19→    box-sizing:border-box;
    20→    color:#202223;
    21→  ">
    22→    <p style="font-size:16px;font-weight:600;margin:0 0 16px;">Check Delivery Availability</p>
    23→    <div style="display:flex;gap:8px;margin-bottom:12px;">
    24→      <input
    25→        type="text"
    26→        placeholder="Enter your zip code"
    27→        disabled
    28→        style="
    29→          flex:1;padding:10px 12px;border:1px solid #c9cccf;border-radius:8px;
    30→          font-size:14px;background:#fafbfb;color:#202223;min-width:0;
    31→        "
    32→      >
    33→      <button
    34→        type="button"
    35→        disabled
    36→        style="
    37→          background:#008060;color:#fff;border:none;border-radius:8px;
    38→          padding:10px 20px;font-size:14px;font-weight:600;white-space:nowrap;
    39→          opacity:0.7;cursor:default;
    40→        "
    41→      >Check</button>
    42→    </div>
    43→    <div style="
    44→      background:#00806015;border-left:3px solid #008060;border-radius:8px;
    45→      padding:12px;font-size:14px;color:#008060;line-height:1.4;
    46→    ">
    47→      Great news! We deliver to your area.
    48→      <div style="margin-top:4px;font-size:13px;opacity:0.8;">Estimated delivery: 2-3 business days</div>
    49→    </div>
    50→    <p style="margin:12px 0 0;font-size:11px;color:#8c9196;text-align:center;">
    51→      Zip Code Checker — live widget loads on your storefront
    52→    </p>
    53→  </div>
    54→{% else %}
    55→
    56→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
    57→
    58→<div
    59→  id="zcc-widget-{{ block.id }}"
    60→  data-shop="{{ shop.permanent_domain }}"
    61→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
    62→  data-block="{{ block.id }}"
    63→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
    64→  {{ block.shopify_attributes }}
    65→></div>
    66→
    67→<script>
    68→(function () {
    69→  var ROOT_ID = "zcc-widget-{{ block.id }}";
    70→  var container = document.getElementById(ROOT_ID);
    71→  if (!container) return;
    72→
    73→  var SHOP = container.dataset.shop;
    74→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
    75→
    76→  // Try embedded config from metafield first (instant, no network needed)
    77→  var configStr = container.getAttribute("data-config");
    78→  if (configStr) {
    79→    try {
    80→      renderWidget(JSON.parse(configStr));
    81→      return;
    82→    } catch (e) {
    83→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
    84→    }
    85→  }
    86→
    87→  // Fallback: fetch config from API
    88→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
    89→    .then(function (r) {
    90→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
    91→      return r.json();
    92→    })
    93→    .then(function (cfg) { renderWidget(cfg); })
    94→    .catch(function (err) {
    95→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
    96→      renderWidget({});
    97→    });
    98→
    99→  function renderWidget(cfg) {
   100→    // Merge with defaults
   101→    var D = {
   102→      position: "inline",
   103→      heading: "Check Delivery Availability",
   104→      placeholder: "Enter your zip code",
   105→      buttonText: "Check",
   106→      successMessage: "Great news! We deliver to your area.",
   107→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
   108→      notFoundMessage: "This zip code was not found in our system.",
   109→      primaryColor: "#008060",
   110→      successColor: "#008060",
   111→      errorColor: "#D72C0D",
   112→      backgroundColor: "#FFFFFF",
   113→      textColor: "#202223",
   114→      borderRadius: "8",
   115→      showEta: true,
   116→      showZone: false,
   117→      showWaitlistOnFailure: false,
   118→      customCss: "",
   119→    };
   120→    Object.keys(D).forEach(function (k) {
   121→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
   122→    });
   123→
   124→    var rad = cfg.borderRadius + "px";
   125→    var WID = "zcc-" + ROOT_ID;
   126→
   127→    if (cfg.position === "floating") {
   128→      renderFloating(cfg, WID, rad);
   129→    } else if (cfg.position === "popup") {
   130→      renderPopup(cfg, WID, rad);
   131→    } else {
   132→      renderInline(cfg, WID, rad);
   133→    }
   134→  }
   135→
   136→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
   137→  function injectCss(wid, cfg, rad) {
   138→    var css =
   139→      "#" + wid + "{" +
   140→        "background:" + cfg.backgroundColor + " !important;" +
   141→        "color:" + cfg.textColor + " !important;" +
   142→        "border-radius:" + rad + " !important;" +
   143→        "padding:24px !important;" +
   144→        "border:1px solid #e1e3e5 !important;" +
   145→        "max-width:480px;" +
   146→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
   147→        "box-sizing:border-box !important;" +
   148→      "}" +
   149→      "#" + wid + " *{box-sizing:border-box !important}" +
   150→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
   151→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
   152→      "#" + wid + " .zcc-input{" +
   153→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
   154→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
   155→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
   156→      "}" +
   157→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
   158→      "#" + wid + " .zcc-btn{" +
   159→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   160→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
   161→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
   162→      "}" +
   163→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
   164→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
   165→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
   166→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
   167→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
   168→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
   169→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
   170→      "#" + wid + " .zcc-wl-input{" +
   171→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
   172→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
   173→      "}" +
   174→      "#" + wid + " .zcc-wl-btn{" +
   175→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
   176→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
   177→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
   178→      "}" +
   179→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
   180→      (cfg.customCss || "");
   181→
   182→    var styleEl = document.createElement("style");
   183→    styleEl.textContent = css;
   184→    document.head.appendChild(styleEl);
   185→  }
   186→
   187→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
   188→  function buildWidgetInner(wid, cfg, btnLabel) {
   189→    return (
   190→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
   191→      '<div class="zcc-row">' +
   192→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
   193→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
   194→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
   195→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
   196→      "</div>" +
   197→      '<div id="' + wid + '-res"></div>'
   198→    );
   199→  }
   200→
   201→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   202→    var inp = document.getElementById(wid + "-inp");
   203→    var btn = document.getElementById(wid + "-btn");
   204→    var res = document.getElementById(wid + "-res");
   205→    var btnLabel = cfg.buttonText;
   206→    if (!inp || !btn || !res) return;
   207→
   208→    function checkZip() {
   209→      var zip = inp.value.trim();
   210→      if (!zip) { inp.focus(); return; }
   211→
   212→      btn.disabled = true;
   213→      btn.textContent = "\u2026";
   214→      res.innerHTML = "";
   215→
   216→      fetch(
   217→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   218→          "&zip=" + encodeURIComponent(zip)
   219→      )
   220→        .then(function (r) { return r.json(); })
   221→        .then(function (data) {
   222→          btn.disabled = false;
   223→          btn.textContent = btnLabel;
   224→
   225→          if (data.allowed) {
   226→            var html = '<div class="zcc-result ok">' + esc(data.message);
   227→            if (cfg.showEta && data.eta) {
   228→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   229→            }
   230→            if (cfg.showZone && data.zone) {
   231→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   232→            }
   233→            if (data.daysOfWeek) {
   234→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   235→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
   236→            }
   237→            if (data.cutoffTime) {
   238→              var parts = data.cutoffTime.split(':');
   239→              var hr = parseInt(parts[0], 10);
   240→              var min = parts[1] || '00';
   241→              var ampm = hr >= 12 ? 'PM' : 'AM';
   242→              var hr12 = hr % 12 || 12;
   243→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
   244→            }
   245→            html += "</div>";
   246→            res.innerHTML = html;
   247→          } else {
   248→            var html = '<div class="zcc-result fail">' + esc(data.message);
   249→            if (cfg.showWaitlistOnFailure) {
   250→              html +=
   251→                '<div class="zcc-wl">' +
   252→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
   253→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
   254→                "</div>";
   255→            }
   256→            html += "</div>";
   257→            res.innerHTML = html;
   258→
   259→            if (cfg.showWaitlistOnFailure) {
   260→              var wBtn = document.getElementById(wid + "-wl-btn");
   261→              if (wBtn) {
   262→                wBtn.addEventListener("click", function () {
   263→                  var emailEl = document.getElementById(wid + "-wl-email");
   264→                  var email = emailEl ? emailEl.value.trim() : "";
   265→                  if (!email) { if (emailEl) emailEl.focus(); return; }
   266→                  joinWaitlist(zip, email, wBtn);
   267→                });
   268→              }
   269→            }
   270→          }
   271→        })
   272→        .catch(function () {
   273→          btn.disabled = false;
   274→          btn.textContent = btnLabel;
   275→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
   276→        });
   277→    }
   278→
   279→    btn.addEventListener("click", checkZip);
   280→    inp.addEventListener("keydown", function (e) {
   281→      if (e.key === "Enter") checkZip();
   282→    });
   283→  }
   284→
   285→  function joinWaitlist(zip, email, wBtn) {
   286→    wBtn.disabled = true;
   287→    wBtn.textContent = "Joining\u2026";
   288→
   289→    fetch(API_BASE + "/api/waitlist", {
   290→      method: "POST",
   291→      headers: { "Content-Type": "application/json" },
   292→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
   293→    })
   294→      .then(function (r) { return r.json(); })
   295→      .then(function (data) {
   296→        var wlEl = wBtn.closest(".zcc-wl");
   297→        if (data.success) {
   298→          if (wlEl) wlEl.innerHTML =
